parameters.jsCode:
/**
 * n8n Code Node
 * Run Once for All Items
 *
 * - Parse document_annotation
 * - Merge annotation ke record
 * - title selalu diambil dari annotation
 * - Array top-level → object dengan key "0", "1", ...
 * - Array kosong → {}
 * - pricing → object terstruktur
 * - Field null / "null" → null
 */

const FIELDS_TO_MERGE = [
  "organizer",
  "categories",
  "level",
  "startDate",
  "endDate",
  "format",
  "participationType",
  "pricing",
  "location",
  "url",
];

const FIELDS_ALWAYS_OVERWRITE = [
  "title",
];

/**
 * Membersihkan value.
 */
function cleanValue(value) {
  if (
    value === null ||
    value === undefined ||
    value === "null"
  ) {
    return null;
  }

  return value;
}

/**
 * Parse pricing string menjadi object.
 */
function parsePricing(raw) {
  if (raw === null || raw === undefined || raw === "null") {
    return null;
  }

  if (typeof raw !== "string") {
    return raw;
  }

  const trimmed = raw.trim();

  if (!trimmed) {
    return null;
  }

  if (/^(gratis|free)$/i.test(trimmed)) {
    return {
      type: "free",
      raw: trimmed,
    };
  }

  try {
    const tiers = trimmed
      .split(";")
      .map((s) => s.trim())
      .filter(Boolean)
      .map((waveStr) => {
        // Ambil label gelombang
        const waveLabelMatch =
          waveStr.match(/\(([^)]+)\)\s*$/);

        const wave = waveLabelMatch
          ? waveLabelMatch[1].trim()
          : null;

        const withoutWaveLabel = waveLabelMatch
          ? waveStr
              .slice(0, waveLabelMatch.index)
              .trim()
          : waveStr;

        // Ambil unit setelah /
        const unitMatch =
          withoutWaveLabel.match(/\/([^/]+)$/);

        const unit = unitMatch
          ? unitMatch[1].trim()
          : null;

        const amountsPart = unitMatch
          ? withoutWaveLabel
              .slice(0, unitMatch.index)
              .trim()
          : withoutWaveLabel;

        const amounts = amountsPart
          .split(",")
          .map((s) => {
            const number = Number(
              s.replace(/[^\d]/g, "")
            );

            return number;
          })
          .filter((n) => !Number.isNaN(n));

        return {
          wave,
          unit,
          amounts,
        };
      });

    const hasAmounts = tiers.some(
      (tier) => tier.amounts.length > 0
    );

    if (!hasAmounts) {
      return {
        type: "unparsed",
        raw: trimmed,
      };
    }

    return {
      type: "paid",
      raw: trimmed,
      tiers,
    };
  } catch {
    return {
      type: "unparsed",
      raw: trimmed,
    };
  }
}

/**
 * Transformer khusus field.
 */
const TRANSFORMERS = {
  pricing: parsePricing,
};

/**
 * Array → Object
 *
 * ["A", "B"]
 *
 * menjadi:
 *
 * {
 *   "0": "A",
 *   "1": "B"
 * }
 *
 * [] → {}
 */
function arrayToObject(value) {
  if (!Array.isArray(value)) {
    return value;
  }

  return Object.fromEntries(
    value
      .filter(
        (item) =>
          item !== null &&
          item !== undefined &&
          item !== "null"
      )
      .map((item, index) => [
        String(index),
        item,
      ])
  );
}

/**
 * Convert semua array top-level
 * menjadi object untuk kompatibilitas
 * dengan field JSONB di n8n Postgres.
 */
function convertTopLevelArraysToObjects(record) {
  const result = {
    ...record,
  };

  for (const key of Object.keys(result)) {
    if (Array.isArray(result[key])) {
      result[key] = arrayToObject(result[key]);
    }
  }

  return result;
}

/**
 * Cek apakah value kosong.
 */
function isEmpty(value) {
  if (
    value === null ||
    value === undefined ||
    value === "null"
  ) {
    return true;
  }

  if (Array.isArray(value)) {
    return value.length === 0;
  }

  if (
    typeof value === "object" &&
    Object.keys(value).length === 0
  ) {
    return true;
  }

  return false;
}

/**
 * Merge document_annotation ke record.
 */
function mergeAnnotation(record, overwrite = false) {
  const result = {
    ...record,
  };

  let annotation;

  try {
    annotation =
      typeof record.document_annotation === "string"
        ? JSON.parse(record.document_annotation)
        : record.document_annotation;
  } catch {
    return result;
  }

  if (
    !annotation ||
    typeof annotation !== "object"
  ) {
    return result;
  }

  // title selalu overwrite
  for (const field of FIELDS_ALWAYS_OVERWRITE) {
    if (field in annotation) {
      result[field] =
        cleanValue(annotation[field]);
    }
  }

  // Field lainnya hanya diisi kalau kosong
  for (const field of FIELDS_TO_MERGE) {
    if (!(field in annotation)) {
      continue;
    }

    const currentValue = result[field];

    if (
      overwrite ||
      isEmpty(currentValue)
    ) {
      const rawValue =
        annotation[field];

      const transformer =
        TRANSFORMERS[field];

      result[field] = transformer
        ? transformer(rawValue)
        : cleanValue(rawValue);
    }
  }

  return result;
}


// =====================================================
// MAIN
// =====================================================

const OVERWRITE = false;

return $input.all().map((item) => {
  const merged = mergeAnnotation(
    item.json,
    OVERWRITE
  );

  const converted =
    convertTopLevelArraysToObjects(
      merged
    );

  // document_annotation tidak perlu
  // dikirim ke database
  delete converted.document_annotation;

  return {
    json: converted,
  };
});

